import { Component } from '@angular/core';
import { Order } from '../models/orders';
import { NarudzbineService } from '../narudzbine.service';
import jwt_decode from 'jwt-decode'; // Uvezi jwt-decode

@Component({
  selector: 'app-poslati-artikli',
  templateUrl: './poslati-artikli.component.html',
  styleUrls: ['./poslati-artikli.component.css']
})
export class PoslatiArtikliComponent {
  narudzbine: Order[] = [];
  storeId: string = ''; // ID prodavnice
  successMessage: string | null = null; // Poruka o uspehu

  constructor(private narudzbineService: NarudzbineService) {}

  ngOnInit(): void {
    const token = localStorage.getItem('token');
    if (token) {
      const decodedToken: any = jwt_decode(token);
      this.storeId = decodedToken.id; // Pretpostavka da token sadrži prodavnicu ID
      this.fetchOrders(); // Dohvati poručene artikle
    }
  }

  fetchOrders() {
    this.narudzbineService.dohvatiNarudzbineZaProdavnicu(this.storeId, "Poslato").subscribe(
      (response: Order[]) => {
        this.narudzbine = response;

      },
      (error) => {
        console.error('Greška pri dohvatanju poručenih artikala:', error);
      }
    );
  }




  getStarsArray(count: number): number[] {
    return Array(count).fill(0);  // Niz sa brojem elemenata jednakim oceni
  }

  getArtikalImage(imagePath: string): string {
    return `http://localhost:4000/${imagePath}`;
  }


}
